package com.owuor.educue.finance.claims;
import com.owuor.educue.common.storage.FileStorageService;import lombok.RequiredArgsConstructor;import lombok.extern.slf4j.Slf4j;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Component;import org.springframework.transaction.annotation.Transactional;import java.time.LocalDateTime;import java.util.*;
@Component @RequiredArgsConstructor @Slf4j public class DebitClaimWorker {private final DebitClaimBatchRepository repository;private final DebitClaimQueueService queue;private final DebitClaimSpreadsheet spreadsheet;private final DebitClaimItemProcessor processor;private final FileStorageService storage;
 @Scheduled(fixedDelayString="${app.finance.debit-claim-worker-delay-ms:3000}") public void drain(){for(Long id:queue.claimNext())process(id);}
 void process(Long id){var batch=repository.findById(id).orElseThrow();List<DebitClaimSpreadsheet.Row> results=new ArrayList<>();try(var input=storage.load(batch.getSourceUrl()).getInputStream()){for(var row:spreadsheet.read(input)){try{String message=processor.post(batch,row);results.add(new DebitClaimSpreadsheet.Row(row.number(),row.studentId(),row.admission(),row.studentName(),row.amount(),"SUCCESS",message));batch.setSuccessfulRows(batch.getSuccessfulRows()+1);}catch(Exception e){results.add(new DebitClaimSpreadsheet.Row(row.number(),row.studentId(),row.admission(),row.studentName(),row.amount(),"ERROR",message(e)));batch.setFailedRows(batch.getFailedRows()+1);}batch.setProcessedRows(batch.getProcessedRows()+1);batch=repository.saveAndFlush(batch);}batch.setResultUrl(storage.store(spreadsheet.result(results),"debit-claim-results-"+batch.getUuid()+".xlsx","application/vnd.openxmlformats-officedocument.spreadsheetml.sheet","debit-claims/"+batch.getUuid()));batch.setStatus(batch.getFailedRows()==0?"COMPLETED":"COMPLETED_WITH_ERRORS");batch.setCompletedAt(LocalDateTime.now());batch=repository.saveAndFlush(batch);log.info("Debit claim batch {} completed: {} successful, {} failed",batch.getUuid(),batch.getSuccessfulRows(),batch.getFailedRows());}catch(Exception e){String failure=message(e);var failedBatch=repository.findById(id).orElse(null);if(failedBatch!=null){failedBatch.setStatus("FAILED");failedBatch.setLastError(failure);repository.saveAndFlush(failedBatch);log.warn("Debit claim batch {} failed: {}",failedBatch.getUuid(),failure);}else log.warn("Debit claim batch {} disappeared while processing: {}",id,failure);}}
 String message(Exception e){String m=e.getMessage();return m==null?e.getClass().getSimpleName():m.substring(0,Math.min(900,m.length()));}
}
